            sb.append("BASIC PROPERTIES:\n");
            sb.append("  Vertices: ").append(getVertexCount()).append("\n");
            sb.append("  Edges: ").append(getEdgeCount()).append("\n");
            sb.append("  Connected: ").append(isConnected()).append("\n");
